def wrap(s, size, maxw):
    f = F(size)
    PUNCT = "！？。，、；：…—!?"
    lines, cur = [], ""
    for ch in s:
        if f.getlength(cur + ch) > maxw and cur:
            # 标点悬挂: 避免标点单独成行
            if ch in PUNCT and f.getlength(cur + ch) <= maxw + 60:
                lines.append(cur + ch)
                cur = ""
                continue
            lines.append(cur)
            cur = ch
        else:
            cur += ch

